def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Extract the coordinates and values from the grid_values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if value != 0:
            grid[x-1][y-1] = value

    # Initialize DP matrices to store maximum value at each cell
    dp_up = [[0] * N for _ in range(N)]
    dp_down = [[0] * N for _ in range(N)]

    # Upward path
    curr_col = 0
    for row in range(N):
        for col in range(curr_col, N):
            if col == 0:
                dp_up[row][col] = grid[row][col]
            else:
                dp_up[row][col] = max(dp_up[row][col-1], dp_up[row][col]) + grid[row][col]
            curr_col += 1

    # Downward path
    curr_col = N - 1
    for row in range(N):
        for col in range(curr_col, -1, -1):
            if col == N - 1:
                dp_down[row][col] = grid[row][col]
            else:
                dp_down[row][col] = max(dp_down[row][col+1], dp_down[row][col]) + grid[row][col]
            curr_col -= 1

    # Calculate the maximum sum from both paths
    max_sum = float('-inf')
    for row in range(N):
        for col in range(N):
            if dp_up[row][col] > dp_down[row][col]:
                max_sum = max(max_sum, dp_up[row][col])
            else:
                max_sum = max(max_sum, dp_down[row][col])

    return max_sum
```

