def max_energy(beads):
    n = len(beads)

    dp = [[0, 0] for _ in range(n)]  # dp[i][0] will store maximum energy for i beads starting with i-th bead, dp[i][1] for starting without the i-th bead

    # Base case: Calculate the energy for the first bead
    dp[0][0] = beads[0] * beads[0]
    dp[0][1] = 0

    # Fill the DP table
    for i in range(1, n):
        for j in range(i + 1):
            if j == i:
                # If the last bead and the current bead match, we can start from the current bead
                dp[i][0] += beads[i] * beads[i]
            else:
                # The maximum energy comes from either including or excluding the current bead
                dp[i][0] = max(dp[i][0], dp[j][0] + beads[i] * beads[j])
                dp[i][1] = max(dp[i][1], dp[j - 1][0] + beads[j] * beads[i])

    # The maximum energy release is the maximum energy from either a starting with the first bead or not
    return max(dp[-1])
```

