def decode(encoded: str, original: str, message: str) -> str:
    mapping = {}
    cümle = ""

    # Check for letter mismatch
    if len(encoded) != len(original):
        return "Failed"

    # Construct the mapping
    try:
        for old, new in zip(encoded, original):
            mapping[old] = new
    except:
        return "Failed"

    # Check if all letters are represented in the mapping
    if len(mapping) != len(original):
        return "Failed"

    # Decode the message
    try:
        for char in message:
            if char in mapping:
                cümle += mapping[char]
            else:
                cümle += char
    except:
        return "Failed"

    return cümle
