def largest_prime_factor(n: int) -> int:
    if n < 2:
        return None  # No prime factors for numbers less than 2

    def is_prime(num: int) -> bool:
        """Check if a number is prime."""
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    for factor in range(2, int(math.sqrt(n)) + 1):
        if n % factor == 0:
            while n % factor == 0:
                n //= factor
            if is_prime(factor):
                return factor
    if n > 1:
        if is_prime(n):
            return n
    return None  # No prime factors found
