from typing import *
from collections import *

def count_partitions(n: int, k: int, x: int) -> int:
    memo = {}

    def dp(n, k, x):
        if (n, k, x) in memo:
            return memo[(n, k, x)]

        if k == 1:
            return 1 if n >= x else 0

        result = 0
        for i in range(x, n + 1):
            result += dp(n - i, k - 1, x)

        memo[(n, k, x)] = result
        return result

    return dp(n, k, x)
