def count_sequences(n: int, last: int, memo: dict) -> int:
    if n == 0:
        return 1
    if (n, last) in memo:
        return memo[(n, last)]
    if last == 0 or n > last // 2:
        memo[(n, last)] = 0
        return memo[(n, last)]
    memo[(n, last)] = count_sequences(n, last // 2, memo) + count_sequences(n - 1, last, memo)
    return memo[(n, last)]
