def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    q = y0 // x0

    for a in range(1, q + 1):
        b = q // a
        if gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

