from collections import deque

def generate_numbers(n, rules) -> int:
    visited = set()  # To track visited numbers to avoid duplicates
    queue = deque([(n, {n})])  # Queue to BFS with the original number and its transformation set

    while queue:
        current, transformations = queue.popleft()

        if current in visited:
            continue  # Skip visited numbers

        visited.add(current)

        for rule in rules:
            new_num = current * 10 + rule[0]
            if new_num not in visited:
                transformations.add(new_num)  # Add transformed number to transformation set
                queue.append((new_num, transformations))

    return len(transformations)
