def calculate_score(system, points):
    if system not in [11, 21]:
        raise ValueError("Invalid scoring system. Please use either 11 or 21.")

    score = [0] * len(points)
    game.Score = 0
    lead = 0
    current_player = 0

    for i, move in enumerate(points):
        if move == 'W':
            score[i] = 1
            current_player = 1
        else:
            score[i] = -1
            current_player = 0

        lead += score[i]
        if lead >= system:
            if lead == system + 2:
                game.Score = "{current_player} {lead - system}"
            else:
                game.Score = "{current_player} {lead}"
            break

    if lead < system - 2:
        game.Score = "{current_player} {lead}".format(current_player="Draw")

    return game.Score.split(":")
