def minimum_students_to_leave(heights):
    n = len(heights)
    left_max = [heights[0]] * n
    right_min = [heights[-1]] * n

    # Calculate the maximum height from the start
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], heights[i])

    # Calculate the minimum height from the end
    for i in range(n-2, -1, -1):
        right_min[i] = min(right_min[i+1], heights[i])

    # Count the number of students that need to leave
    leave = 0
    for i in range(n):
        if i > 0 and heights[i] <= left_max[i-1]:
            leave += 1
        if i < n-1 and heights[i] >= right_min[i+1]:
            leave += 1

    return leave
```

